(() => {
  'use strict';
  let host;
  try { host = window.parent; void host.document; }
  catch { console.error('七都终端：需要酒馆助手同源脚本环境'); return; }
  const KEY = 'f7dTacticalTerminal';
  host[KEY]?.dispose?.();
  const clone = value => JSON.parse(JSON.stringify(value));
  const context = () => host.SillyTavern?.getContext?.();
  const listeners = new Set(), cleanups = [];
  let disposed = false, epoch = 0, revision = 0, generating = false, stopped = false;
  let state = { version: 1, status: 'empty', reason: '等待已提交存档', snapshot: null, error: null };
  const session = host.crypto.randomUUID();
  const ids = new WeakMap();
  const identity = m => { if (!ids.has(m)) ids.set(m, host.crypto.randomUUID()); return ids.get(m); };
  const signature = () => {
    const c = context();
    return JSON.stringify([c?.chatId ?? null, c?.characterId ?? null, c?.groupId ?? null,
      (c?.chat || []).map(m => [identity(m), m.swipe_id ?? 0, String(m.mes || '').replace(/<StatusPlaceHolderImpl\/>/g, '').trimEnd()])]);
  };
  const notify = () => { for (const fn of [...listeners]) { try { fn(clone(state)); } catch {} } };
  const clear = reason => { epoch++; state = { version: 1, status: 'empty', reason, snapshot: null, error: null }; notify(); };
  const fail = (code, message) => { state = { version: 1, status: 'error', reason: '', snapshot: null, error: { code, message } }; notify(); };
  const capture = () => ({ epoch, signature: signature(), chatId: context()?.chatId ?? null });
  const valid = t => !disposed && !stopped && t?.epoch === epoch && t.chatId === (context()?.chatId ?? null) && t.signature === signature();
  const string = v => typeof v === 'string' ? v : '';
  const entries = x => x && typeof x === 'object' && !Array.isArray(x) ? Object.entries(x).filter(([k]) => k !== '$meta') : [];
  const list = x => Array.isArray(x) ? x : [];
  const CG_IDS = ['ann_first_meet','antoneva_first_meet','ending_journey','ending_eternal_end','ending_sacrifice_male','ending_sacrifice_female','ending_final_male','ending_final_female','ending_box_male','ending_box_female'];
  const CG_NAMES = ['安·病房初见','安托涅瓦·初见','两个人的旅途','永恒的终焉','牺牲的意义·男指挥使','牺牲的意义·女指挥使','终结·男指挥使','终结·女指挥使','箱庭风景·男指挥使','箱庭风景·女指挥使'];
  const assets = {"ann_first_meet": "data:image/webp;base64,", "antoneva_first_meet": "data:image/webp;base64,", "ending_journey": "data:image/webp;base64,", "ending_eternal_end": "data:image/webp;base64,", "ending_sacrifice_male": "data:image/webp;base64,", "ending_sacrifice_female": "data:image/webp;base64,", "ending_final_male": "data:image/webp;base64,", "ending_final_female": "data:image/webp;base64,", "ending_box_male": "data:image/webp;base64,", "ending_box_female": "data:image/webp;base64,"};
  const albumKey = 'f7d.album.v1';
  const album = s => {
    const unlocks = new Set(list(s.meta?.cg).map(x=>typeof x==='string'?x.replace(/^cg_/,''):'').filter(x => CG_IDS.includes(x)));
    // 已显示的开场图也算解锁；只在已提交存档被接纳时执行。
    for (const id of CG_IDS) if (s.cg_system?.shown?.[id] === true) unlocks.add(id);
    let saved = {}, warning = null, readable = true;
    try { const raw = context()?.accountStorage?.getItem(albumKey);
      saved = raw ? JSON.parse(raw) : {version:1,items:[]};
      if (saved.version !== 1 || !Array.isArray(saved.items)) throw Error('相册版本或格式不兼容'); }
    catch { readable = false; warning = '相册存档读取失败或版本不兼容，旧存档未覆盖'; }
    const existing = Array.isArray(saved.items) ? saved.items.filter(x => CG_IDS.includes(x)) : [];
    const items = [...new Set([...existing, ...unlocks])];
    try {
      const storage = context()?.accountStorage;
      if (!storage) throw Error();
      if (readable) storage.setItem(albumKey, JSON.stringify({ version: 1, items }));
    } catch { warning = '相册暂未保存，请导出备份'; }
    return { enabled: true, warning, items: items.map(id => ({ id, title: CG_NAMES[CG_IDS.indexOf(id)], assetKey: id })) };
  };
  const project = (s, messageId) => {
    const known = new Set(list(s.known));
    const tasks = entries(s.tasks).filter(([,t]) => t?.known === true && ['active','completed','expired','failed'].includes(t.status)).map(([id,t]) => ({
      id, title: string(t.title) || string(t.objective), objective: string(t.objective),
      status: t.status, statusLabel: ({ active:'进行中',completed:'已完成',expired:'已过期',failed:'已失败' })[t.status],
      deadlineLabel: t.deadline_known === true ? string(t.deadline) : '',
    }));
    const contacts = entries(s.terminal?.contacts).filter(([id,c]) => known.has(id) && c?.known === true && c.channel_acquired === true).map(([id,c]) => ({ id, name:string(c.name), channel:string(c.channel), available:c.available === true }));
    const city = list(s.terminal?.city).filter(x => x?.known === true && x.loop === s.loop).map(x => ({ id:string(x.id),title:string(x.title),body:string(x.body) }));
    const journal = list(s.terminal?.journal).filter(x => x?.known === true && x.loop === s.loop).map(x => ({ id:string(x.id),title:string(x.title),body:string(x.body) }));
    const m = context().chat[messageId];
    return { schema:'f7d-terminal-v1', scope:{ chatId:context().chatId, branchId: session+':'+identity(m)+':'+(m.swipe_id ?? 0)+':'+epoch, loop:s.loop },
      revision:session+':'+(++revision), header:{ dayLabel:Number.isInteger(s.day)?'第'+s.day+'天':'', timeLabel:Number.isInteger(s.clock_minutes)?String(Math.floor(s.clock_minutes/60)).padStart(2,'0')+':'+String(s.clock_minutes%60).padStart(2,'0'):'', location:string(s.location) },
      tasks,contacts,city,journal,album:album(s) };
  };
  let pending = null;
  const publish = (ticket, messageId, reader) => {
    if (!valid(ticket)) return false;
    const c = context();
    if (messageId !== c.chat.length - 1 || c.chat[messageId]?.is_system) return false;
    try {
      const data = reader({ type:'message',message_id:messageId });
      const s = data?.stat_data;
      if (!s) { clear('该分支没有已提交数据'); return false; }
      if (s.schema !== 'f7d_textloop_0.4') { fail('SCHEMA_INCOMPATIBLE','卡片变量版本不兼容'); return false; }
      if (!Number.isInteger(s.loop) || s.loop < 1) { fail('INVALID_LOOP','轮回字段无效'); return false; }
      if (generating) { pending = { ticket,messageId,reader }; return true; }
      const oldLoop = state.snapshot?.scope.loop;
      if (oldLoop !== undefined && oldLoop !== s.loop) { clear('进入新轮回'); ticket = capture(); }
      state = { version:1,status:'ready',reason:'',snapshot:project(s,messageId),error:null }; notify(); return true;
    } catch { fail('READ_FAILED','读取已提交存档失败'); return false; }
  };
  const requestIntent = async p => {
    const failure = (code,message) => ({ ok:false,draft:null,inserted:false,error:{code,message} });
    if (state.status !== 'ready' || generating || stopped) return failure('NOT_READY','请等待剧情变量提交完成');
    const snap = state.snapshot;
    if (p?.revision !== snap.revision) return failure('STALE_SNAPSHOT','页面已更新，请重新选择');
    let draft;
    if (p.type === 'contact') {
      const contact = snap.contacts.find(x => x.id === p.id);
      if (!contact?.available) return failure('CONTACT_UNAVAILABLE','当前无法联系这位角色');
      draft = '我打开战术终端，尝试通过'+contact.channel+'联系'+contact.name+'。';
    } else if (p.type === 'viewTask') {
      const task = snap.tasks.find(x => x.id === p.id);
      if (!task) return failure('TASK_UNKNOWN','当前没有这项已知任务');
      draft = '我打开战术终端，查看“'+task.title+'”的已知详情。';
    } else if (p.type === 'viewTerminal') draft = '我打开战术终端，查看当前已知信息。';
    else return failure('INVALID_INTENT','不支持这项操作');
    const input = host.document.querySelector('#send_textarea');
    if (!input) return { ok:false,draft,inserted:false,error:{code:'COMPOSER_MISSING',message:'输入框不可用，草稿已保留'} };
    if (String(input.value || '').length) return { ok:false,draft,inserted:false,error:{code:'COMPOSER_OCCUPIED',message:'输入框已有文字，请先自行合并草稿'} };
    const setter = Object.getOwnPropertyDescriptor(host.HTMLTextAreaElement.prototype,'value')?.set;
    if (setter) setter.call(input,draft); else input.value=draft;
    input.dispatchEvent(new host.Event('input',{bubbles:true})); input.focus();
    return { ok:true,draft,inserted:true,error:null };
  };
  const api = { version:1, getSnapshot: () => clone(state), getAsset(id) {
    if(!state.snapshot?.album.items.some(x=>x.assetKey===id))return null;
    const value=assets[id];return typeof value==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(value)?value:null;
  }, exportAlbum() {
    return context()?.accountStorage?.getItem(albumKey) || JSON.stringify({version:1,items:[]});
  }, subscribe(fn) {
    if (typeof fn !== 'function') throw TypeError('订阅者必须是函数');
    listeners.add(fn); try { fn(clone(state)); } catch {}
    return () => listeners.delete(fn);
  }, requestIntent, dispose() {
    if (disposed) return; clear('提供者已卸载'); disposed=true; pending=null;
    cleanups.splice(0).forEach(fn=>fn()); listeners.clear();
    if (host[KEY] === api) delete host[KEY];
    if (host.__f7dCommitBridge === writer) delete host.__f7dCommitBridge;
  } };
  const writer = { capture, valid, publish, invalidate:clear, fail };
  host[KEY]=api; host.__f7dCommitBridge=writer;
  const c = context();
  for (const name of ['CHAT_CHANGED','MESSAGE_SWIPED','MESSAGE_SWIPE_DELETED','MESSAGE_EDITED','MESSAGE_DELETED','CHARACTER_FIRST_MESSAGE_SELECTED']) {
    const type = c?.eventTypes?.[name]; if (!type) continue;
    const fn = () => { pending=null;generating=false;stopped=false;clear('聊天或消息分支已改变，等待重新读取'); if(name !== 'MESSAGE_EDITED')host.dispatchEvent(new host.Event('f7d:reload-committed')); };
    c.eventSource.on(type,fn); c.eventSource.makeFirst?.(type,fn); cleanups.push(()=>c.eventSource.removeListener(type,fn));
  }
  const bind = (name,fn) => { const type=c?.eventTypes?.[name]; if(type){c.eventSource.on(type,fn);c.eventSource.makeFirst?.(type,fn);cleanups.push(()=>c.eventSource.removeListener(type,fn));} };
  bind('GENERATION_STARTED',(type,options,dryRun)=>{ if(dryRun||type==='quiet')return;generating=true;stopped=false;pending=null;clear('剧情生成中'); });
  bind('GENERATION_STOPPED',()=>{generating=false;stopped=true;pending=null;clear('生成已中止，等待下一次有效提交');});
  bind('GENERATION_ENDED',()=>{generating=false;if(stopped)return; const p=pending;pending=null;if(p)publish(p.ticket,p.messageId,p.reader);});
  // 消息追加会改变分支签名；立即清空，等待该楼层写入完成。
  bind('MESSAGE_SENT',()=>{ pending=null;clear('等待玩家消息变量提交'); });
  bind('MESSAGE_RECEIVED',()=>{ pending=null;clear('等待回复变量提交'); });
  const unload=()=>api.dispose();window.addEventListener('pagehide',unload);cleanups.push(()=>window.removeEventListener('pagehide',unload));
  host.dispatchEvent(new host.Event('f7d:provider-ready'));
})();

(() => {
  const KEY='__F7D_CARD_CHOICE_BRIDGE_V0424__';
  const doc=window.parent?.document||document;
  const host=window.parent||window;
  let generating=false, disposed=false, timer=null;
  const context=()=>host.SillyTavern?.getContext?.();
  const busy=()=>{
    const stream=context()?.streamingProcessor;
    return generating||Boolean(stream&&!stream.isFinished&&!stream.isStopped);
  };
  const subscriptions=[];
  const start=(type,options,dryRun)=>{
    if(dryRun||type==='quiet') return;
    generating=true;
  };
  const end=()=>{generating=false;refresh();};
  const choice='[data-f7d-choice="1"]';
  const free='[data-f7d-choice-free="1"]';
  const input=()=>doc.querySelector('#send_textarea');
  const focus=el=>{ try{el?.focus({preventScroll:true});}catch{el?.focus();} };
  const choiceStyle='box-sizing:border-box;display:block;width:100%;min-height:68px;padding:1em 2.6em 1em 3.9em;border:1px solid rgba(107,119,110,.27);border-radius:7px;background:rgba(255,255,253,.97);box-shadow:none;color:#202724;font:640 14px/1.58 system-ui,-apple-system,Microsoft YaHei,sans-serif;text-align:left;cursor:pointer;overflow-wrap:anywhere;word-break:break-word;';
  const freeStyle='box-sizing:border-box;display:block;grid-column:1/-1;width:100%;min-height:44px;padding:.72em 2.6em;border:1px solid rgba(107,119,110,.28);border-radius:7px;background:rgba(246,248,245,.9);box-shadow:none;color:#536158;font:620 13.5px/1.45 system-ui,-apple-system,Microsoft YaHei,sans-serif;text-align:center;cursor:pointer;overflow-wrap:anywhere;';
  const gridStyle='box-sizing:border-box;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.72em;width:100%;max-width:100%;margin:.9em 0;padding:1em;border:1px solid rgba(107,119,110,.24);border-radius:10px;background:rgba(250,250,247,.96);box-shadow:0 8px 22px rgba(35,42,38,.07);';
  const terminalStyle='box-sizing:border-box;width:100%;max-width:100%;overflow-wrap:anywhere;margin:.82em 0;padding:.82em .95em;border:1px solid rgba(107,119,110,.26);border-radius:8px;background:rgba(249,250,247,.94);box-shadow:none;color:#4b5650;font:560 13px/1.65 system-ui,-apple-system,Microsoft YaHei,sans-serif;white-space:pre-wrap';
  const themeCss=`
[data-f7d-terminal="1"]{position:relative!important;border:1px solid rgba(107,119,110,.26)!important;border-radius:8px!important;background:rgba(249,250,247,.94)!important;color:#4b5650!important;box-shadow:none!important;overflow:hidden!important}
[data-f7d-terminal="1"]::before{content:"TACTICAL TERMINAL";display:block;margin:-.82em -.95em .65em;padding:.5em .9em;border-bottom:1px solid rgba(107,119,110,.16);background:rgba(244,246,242,.84);color:#909894;font:650 9px/1.2 system-ui,-apple-system,Microsoft YaHei,sans-serif;letter-spacing:.18em;text-align:left}
[data-f7d-choice-grid="1"]{position:relative!important;isolation:isolate;counter-reset:f7dChoice}
[data-f7d-choice-title-mark="1"]{flex:0 0 auto}
[data-f7d-choice="1"]{counter-increment:f7dChoice;position:relative!important;transition:border-color .14s ease,background .14s ease,transform .14s ease!important}
[data-f7d-choice="1"]::before{content:counter(f7dChoice,decimal-leading-zero);position:absolute;left:15px;top:50%;transform:translateY(-50%);color:#51655a;font:750 12px/1 system-ui,-apple-system,Microsoft YaHei,sans-serif;letter-spacing:.04em}
[data-f7d-choice="1"]::after{content:"›";position:absolute;right:15px;top:50%;transform:translateY(-52%);color:#74827a;font:400 22px/1 system-ui,-apple-system,Microsoft YaHei,sans-serif;transition:transform .14s ease,color .14s ease}
[data-f7d-choice="1"]:hover{transform:translateY(-1px)!important;border-color:rgba(83,103,91,.46)!important;background:rgba(249,251,247,.99)!important}
[data-f7d-choice="1"]:hover::after{transform:translate(2px,-52%);color:#51665a}
[data-f7d-choice="1"]:active{transform:translateY(0)!important;background:rgba(245,248,244,.99)!important}
[data-f7d-choice="1"]:focus-visible,[data-f7d-choice-free="1"]:focus-visible{outline:2px solid rgba(188,163,91,.48)!important;outline-offset:2px!important}
[data-f7d-choice-kind="slack"]{border-color:rgba(132,137,134,.22)!important;background:rgba(247,247,245,.82)!important;color:#7f8581!important}
[data-f7d-choice-kind="slack"]::before{color:#9a9f9c!important}
[data-f7d-choice-kind="slack"]::after{color:#a4aaa6!important}
[data-f7d-choice-free="1"]{position:relative!important;transition:border-color .14s ease,background .14s ease,color .14s ease!important}
[data-f7d-choice-free="1"]::before{content:"✎";margin-right:.48em;color:#73877b;font-size:12px}
[data-f7d-choice-free="1"]::after{content:"›";position:absolute;right:15px;top:50%;transform:translateY(-52%);color:#849188;font:400 20px/1 system-ui,-apple-system,Microsoft YaHei,sans-serif}
[data-f7d-choice-free="1"]:hover{border-color:rgba(83,103,91,.42)!important;background:rgba(249,250,247,.98)!important;color:#435248!important}
[data-f7d-choice-title="1"]{position:relative;z-index:1}
@media(max-width:640px){
  [data-f7d-choice-grid="1"]{grid-template-columns:1fr!important;padding:.82em!important;border-radius:9px!important;gap:.62em!important}
  [data-f7d-choice-title="1"]{align-items:center!important;padding:.04em .08em .48em!important;font-size:17px!important}
  [data-f7d-choice-title="1"] small{font-size:8px!important;letter-spacing:.18em!important}
  [data-f7d-choice="1"]{font-size:14px!important;min-height:62px!important;padding:.92em 2.45em .92em 3.5em!important;border-radius:7px!important}
  [data-f7d-choice="1"]::before{left:13px}
  [data-f7d-choice="1"]::after{right:13px}
  [data-f7d-choice-free="1"]{min-height:42px!important;border-radius:7px!important}
  [data-f7d-terminal="1"]{border-radius:7px!important;padding:.78em .82em!important}
  [data-f7d-terminal="1"]::before{margin:-.78em -.82em .6em}
}
`;
  const ensureTheme=()=>{
    let style=doc.getElementById('f7d-ui-theme-v0424');
    if(!style){style=doc.createElement('style');style.id='f7d-ui-theme-v0424';doc.head.appendChild(style);}
    if(style.textContent!==themeCss) style.textContent=themeCss;
  };
  let lastKnownStatus=null;
  const ensureStatusHud=()=>{
    const host=window.parent||window;
    const chat=host.SillyTavern?.getContext?.()?.chat;
    if(!Array.isArray(chat)||!chat.length)return;
    const mvu=host.Mvu||window.Mvu;
    let state=null;
    for(let i=chat.length-1;i>=0&&i>=chat.length-6;i--){
      if(chat[i]?.is_user)continue;
      try{state=mvu?.getMvuData?.({type:'message',message_id:i})?.stat_data||null}catch{}
      if(state?.schema==='f7d_textloop_0.4')break;
    }
    if(state?.schema==='f7d_textloop_0.4')lastKnownStatus=state;
    const s=lastKnownStatus;if(!s)return;
    const anchor=doc.querySelector('#send_form')||doc.querySelector('#chat');if(!anchor)return;
    let hud=doc.getElementById('f7d-status-hud-v0428');
    if(!hud){hud=doc.createElement('div');hud.id='f7d-status-hud-v0428';hud.setAttribute('data-f7d-status-hud','1');hud.style.cssText='box-sizing:border-box;width:min(100%,720px);margin:0 auto 4px;padding:7px 12px;border:1px solid #cbd6c7;border-radius:8px;background:#f8faf4;color:#456050;font:600 12px/1.45 system-ui,Microsoft YaHei,sans-serif;text-align:center;pointer-events:none;';}
    if(anchor.id==='send_form'){
      if(anchor.parentElement&&(hud.parentElement!==anchor.parentElement||hud.nextElementSibling!==anchor))anchor.parentElement.insertBefore(hud,anchor);
    }else if(hud.parentElement!==anchor||anchor.lastElementChild!==hud)anchor.appendChild(hud);
    const minutes=Number(s.clock_minutes);if(!Number.isFinite(minutes))return;
    const hh=String(Math.floor(minutes/60)).padStart(2,'0');const mm=String(minutes%60).padStart(2,'0');
    const label='第'+s.day+'天 · '+hh+':'+mm+' · '+String(s.location||'交界都市');
    if(hud.textContent!==label)hud.textContent=label;
  };
  const classifyChoices=()=>{
    for(const el of doc.querySelectorAll(choice)){
      const t=String(el.textContent||'');
      const slack=/什么都不做|任由.{0,16}(?:过去|流逝)|放弃今天|跳过今天|摆烂/i.test(t);
      el.setAttribute('data-f7d-choice-kind',slack?'slack':'story');
    }
    for(const el of doc.querySelectorAll(free)) el.setAttribute('data-f7d-choice-kind','free');
  };
  const setComposer=text=>{
    const el=input();
    if(!el) return false;
    const value=String(text||'').trim();
    if(!value) return false;
    const ParentTextarea=window.parent?.HTMLTextAreaElement||HTMLTextAreaElement;
    const proto=el instanceof ParentTextarea?ParentTextarea.prototype:HTMLTextAreaElement.prototype;
    const setter=Object.getOwnPropertyDescriptor(proto,'value')?.set;
    if(setter) setter.call(el,value); else el.value=value;
    const ParentEvent=window.parent?.Event||Event;
    el.dispatchEvent(new ParentEvent('input',{bubbles:true}));
    el.dispatchEvent(new ParentEvent('change',{bubbles:true}));
    focus(el);
    return true;
  };
  const makeGrid=items=>{
    const grid=doc.createElement('div');
    grid.setAttribute('data-f7d-choice-grid','1');
    grid.setAttribute('data-f7d-preset-normalized','1');
    grid.style.cssText=gridStyle;
    const title=doc.createElement('div');
    title.setAttribute('data-f7d-choice-title','1');
    title.style.cssText='grid-column:1/-1;display:flex;align-items:end;gap:.8em;padding:.08em .18em .52em;border-bottom:1px solid rgba(107,119,110,.18);color:#202824;font:750 18px/1.2 system-ui,-apple-system,Microsoft YaHei,sans-serif';
    title.innerHTML='<span data-f7d-choice-title-mark="1" style="display:block;width:4px;height:24px;border-radius:1px;background:#c8a957;"></span><span>选择行动</span><small style="padding-bottom:.12em;color:#8b938e;font:600 9px/1 system-ui,-apple-system,Microsoft YaHei,sans-serif;letter-spacing:.22em;">TACTICAL OPTIONS</small>';
    grid.appendChild(title);
    for(const text of items){
      const b=doc.createElement('button');
      b.type='button';
      b.setAttribute('data-f7d-choice','1');
      b.setAttribute('data-f7d-choice-kind',/什么都不做|任由.{0,16}(?:过去|流逝)|放弃今天|跳过今天|摆烂/i.test(text)?'slack':'story');
      b.style.cssText=choiceStyle;
      b.textContent=text;
      grid.appendChild(b);
    }
    const f=doc.createElement('button');
    f.type='button';
    f.setAttribute('data-f7d-choice-free','1');
    f.setAttribute('data-f7d-choice-kind','free');
    f.style.cssText=freeStyle;
    f.textContent='自由输入';
    grid.appendChild(f);
    return grid;
  };
  const isPresetShell=el=>{
